'use client';
import React, { useEffect, useState } from 'react';

// Live online booking: the Race Car Graphics CRM's booking widget (services, prices, availability, Stripe payment).
// Not generated by scripts/convert_design.py: the converter swaps <div data-lc-booking></div> in a design page for
// <CrmBooking /> (or <CrmBooking mode="gift-card" /> for <div data-lc-booking="gift-card">: buying a gift card).
// Stripe returns to the same page with ?session_id=…, which shows the payment receipt instead.
// Widget docs: race-car-graphics-crm/embed/booking/README.md
export const LEMAN_CAVE_BUSINESS = 'fff9defa-bf3c-4056-bde2-101dd03dba6f';
const WIDGET_SRC = 'https://crm.racecargraphics.uk/embed/booking.js';

const theme = {
  '--crm-accent': '#ED2835',
  '--crm-on-accent': '#09090B',
  '--crm-accent-hover': '#FF4A55',
  '--crm-accent-strong': '#FF5C66',
  '--crm-accent-bright': '#ED2835',
  '--crm-on-bright': '#09090B',
};

export default function CrmBooking({ mode: screen = 'form' }) {
  const [mode, setMode] = useState(null);
  const [page, setPage] = useState('/book');

  useEffect(() => {
    setMode(new URLSearchParams(window.location.search).has('session_id') ? 'payment-complete' : screen);
    setPage(window.location.pathname || '/book');
    if (!document.querySelector(`script[src="${WIDGET_SRC}"]`)) {
      const s = document.createElement('script');
      s.src = WIDGET_SRC;
      s.defer = true;
      document.body.appendChild(s);
    }
  }, []);

  if (!mode) return <p role="status" style={{ color: '#A1A1AA' }}>Loading…</p>;
  return (
    <div
      key={mode}
      data-crm-booking={mode}
      data-business={LEMAN_CAVE_BUSINESS}
      data-profile="venue"
      data-theme="dark"
      data-payment-url={page}
      data-booking-url="/book"
      data-contact-url="/contact-leman-cave-norwich"
      data-privacy-url="/privacy"
      data-home-url="/"
      style={theme}
    />
  );
}
